-- Inspeção de estrutura e permissões; nenhum dado de carteira. Depois da migração do ciclo 017, os quatro
-- primeiros indicadores devem ser verdadeiros e anon_funcoes_novas, falso.
select (select count(*) from information_schema.columns where table_schema='public' and table_name='ativos' and column_name in ('veiculos_acesso','indexadores_remuneracao','regime_tributario','prazo_resgate_tipo','prazo_resgate_dias','prazo_resgate_unidade','cobertura_fgc')) = 7 as colunas_disponiveis,
  (select count(*) from pg_constraint where conrelid = 'public.ativos'::regclass and conname in ('ativos_veiculos_acesso_check','ativos_indexadores_remuneracao_check','ativos_regime_tributario_check','ativos_cobertura_fgc_check','ativos_prazo_resgate_check')) = 5 as restricoes_disponiveis,
  has_function_privilege('authenticated','public.cadastrar_ativo_com_atributos(text,public.tipo_ajuste,uuid,text,uuid,boolean,boolean,boolean,boolean,text[],text[],text,text,integer,text,text)','execute') and has_function_privilege('authenticated','public.editar_ativo_com_atributos(uuid,text,uuid,text,uuid,boolean,boolean,boolean,boolean,text[],text[],text,text,integer,text,text)','execute') as authenticated_funcoes_novas,
  has_function_privilege('authenticated','public.cadastrar_ativo_taxonomia(text,public.tipo_ajuste,uuid,text,uuid,boolean,boolean,boolean,boolean)','execute') and has_function_privilege('authenticated','public.editar_ativo_com_nome(uuid,text,uuid,text,uuid,boolean,boolean,boolean,boolean)','execute') as authenticated_funcoes_anteriores,
  has_function_privilege('anon','public.cadastrar_ativo_com_atributos(text,public.tipo_ajuste,uuid,text,uuid,boolean,boolean,boolean,boolean,text[],text[],text,text,integer,text,text)','execute') or has_function_privilege('anon','public.editar_ativo_com_atributos(uuid,text,uuid,text,uuid,boolean,boolean,boolean,boolean,text[],text[],text,text,integer,text,text)','execute') as anon_funcoes_novas;
